I have recreated a synthetic example that show the issue and the difference of behaviour with the Sprite

```rust
use bevy::{prelude::*, sprite::MaterialMesh2dBundle};

fn main() {
    App::new()
        .add_plugins(DefaultPlugins)
        .add_startup_system(setup)
        .add_system(inputs)
        .run();
}

fn setup(
    mut commands: Commands,
    mut meshes: ResMut<Assets<Mesh>>,
    mut materials: ResMut<Assets<ColorMaterial>>,
    asset_server: Res<AssetServer>,
) {
    commands.spawn_bundle(OrthographicCameraBundle::new_2d());
    let image: Handle<Image> = asset_server.load("branding/icon.png");
    commands.insert_resource(image.clone());
    commands.spawn_bundle(MaterialMesh2dBundle {
        mesh: meshes.add(Mesh::from(shape::Quad::default())).into(),
        transform: Transform::default().with_scale(Vec3::splat(128.)),
        material: materials.add(ColorMaterial::from(image.clone())),
        ..Default::default()
    });
    commands.spawn_bundle(SpriteBundle {
        transform: Transform::from_xyz(-256.0, 0.0, 0.0),
        sprite: Sprite {
            custom_size: Some(Vec2::new(128.0, 128.0)),
            ..Default::default()
        },
        texture: image.clone(),
        ..Default::default()
    });
}

fn inputs(
    inputs: Res<Input<KeyCode>>,
    color_materials: Query<&Handle<ColorMaterial>>,
    mut sprites: Query<&mut Sprite>,
    mut materials: ResMut<Assets<ColorMaterial>>,
    image: Res<Handle<Image>>,
    mut raw_images: ResMut<Assets<Image>>,
) {
    if inputs.just_pressed(KeyCode::Q) {
        let mut raw_image = raw_images.get_mut(image.clone()).unwrap();
        raw_image.data = vec![255u8; raw_image.data.len()];
    }
    if inputs.just_pressed(KeyCode::W) {
        for color_material in color_materials.iter() {
            let mut material = materials.get_mut(color_material).unwrap();
            material.color = Color::PURPLE;
        }
        for mut sprite in sprites.iter_mut() {
            sprite.color = Color::PURPLE;
        }
    }
}
```

